$(document).on("click","#btndelete",function(){

 

 
    Swal.fire({
        title: "Are you sure?",
        text: "You won't be able to revert this!",
        icon: "warning",
        showCancelButton: true,
        confirmButtonColor: "#3085d6",
        cancelButtonColor: "#d33",
        confirmButtonText: "Yes, delete it!"
      }).then((result) => {
        if (result.isConfirmed) {
            let id = $(this).attr("student_id");
                 console.log(id);

            $.ajax({
                type: "post",
             
                url : "../API/sform.php",
                data: {"student_id":id},
                dataType: "text",
                success: function (response) {
                    
                    Swal.fire({
                        title: "Deleted!",
                        text: response.message,
                        icon: "success"
                      
                      });
                      read() ;
                }
            });


        }
      });
   })



















class_name();
function class_name(){

   

    let sendingData = {
        "action" : "class_read"
    }

    $.ajax( {
        method: "POST",
        dataType: "JSON",
        url : "../API/class.php",
        data : sendingData,
        success: function(data){

            let status = data.status;
            let response = data.data;
            let html = '';
            let tr = '';

            if(status){

              //  if(res  == 'department_name'  ) {

                
                response.forEach( res => {

                   html += `<option value="${res['student_id']}">${res['class_name']}</option>`;
                })

                $("#class_id").append(html);
           // }
              
            }else{
                alert("error",response);
            }
           

        },
        error: function(data){

        }
    })

}




Department_name();
function Department_name(){

   

    let sendingData = {
        "action" : "department_read"
    }

    $.ajax( {
        method: "POST",
        dataType: "JSON",
        url : "../Api/department.php",
        data : sendingData,
        success: function(data){

            let status = data.status;
            let response = data.data;
            let html = '';
            let tr = '';

            if(status){

                
                response.forEach( res => {

                   html += `<option value="${res['student_id']}">${res['department_name']}</option>`;
                })

                $("#department_id").append(html);

              
            }else{
                alert("error",response);
            }
           

        },
        error: function(data){

        }
    })

}



